package com.financetrack.serviceImpl;
import com.financetrack.dto.EntryDto; import com.financetrack.dto.EntryDto.Request; import com.financetrack.entity.*; import com.financetrack.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service @Transactional public class EntryService {
 private final IncomeRepository incomes;private final ExpenseRepository expenses;private final CategoryRepository categories;private final UserRepository users;
 public EntryService(IncomeRepository i,ExpenseRepository e,CategoryRepository c,UserRepository u){incomes=i;expenses=e;categories=c;users=u;}
 public List<EntryDto> list(String type,Long uid,LocalDate from,LocalDate to){return (type.equals("income")?incomes.findByUserIdAndOccurredOnBetweenOrderByOccurredOnDesc(uid,from,to):expenses.findByUserIdAndOccurredOnBetweenOrderByOccurredOnDesc(uid,from,to)).stream().map(this::dto).toList();}
 public EntryDto create(String type,Long uid,Request r){User u=users.findById(uid).orElseThrow();Category c=category(r.categoryId(),type);FinancialEntry x=type.equals("income")?incomes.save(new Income(u,c,r.description().trim(),r.amount(),r.occurredOn())):expenses.save(new Expense(u,c,r.description().trim(),r.amount(),r.occurredOn()));return dto(x);}
 public EntryDto update(String type,Long uid,Long id,Request r){FinancialEntry x=type.equals("income")?incomes.findByIdAndUserId(id,uid).orElseThrow(()->new NoSuchElementException("Registro no encontrado")):expenses.findByIdAndUserId(id,uid).orElseThrow(()->new NoSuchElementException("Registro no encontrado"));x.update(category(r.categoryId(),type),r.description().trim(),r.amount(),r.occurredOn());return dto(x);}
 public void delete(String type,Long uid,Long id){FinancialEntry x=type.equals("income")?incomes.findByIdAndUserId(id,uid).orElseThrow(()->new NoSuchElementException("Registro no encontrado")):expenses.findByIdAndUserId(id,uid).orElseThrow(()->new NoSuchElementException("Registro no encontrado"));if(type.equals("income"))incomes.delete((Income)x);else expenses.delete((Expense)x);}
 private Category category(Long id,String type){Category c=categories.findById(id).orElseThrow(()->new IllegalArgumentException("Categoría inválida"));if(!c.getKind().equals(type.equals("income")?"INCOME":"EXPENSE"))throw new IllegalArgumentException("La categoría no corresponde al registro");return c;}
 private EntryDto dto(FinancialEntry x){return new EntryDto(x.getId(),x.getCategory().getName(),x.getDescription(),x.getAmount(),x.getOccurredOn());}
}
